/* license.min.js — DairyNotebook 共通ライセンスUI（LU/MT/GM 共通）
 * 前提: 先に license-core.js を読み込み、window.DN_APP を 'LU'|'MT'|'GM' に設定しておくこと。 */
(function () {
  'use strict';
  var APP = (window.DN_APP || '').toUpperCase();
  var STORAGE_KEY = 'dn_license_v1';
  var TERMS_KEY = 'dn_terms_v1';
  var TERMS_VERSION = 1;
  var CONTACT_LABEL = 'DairyNotebook';
  var PUBLIC_JWK = {"kty":"EC","crv":"P-256","x":"u8G2GYq7BeWhY7htwNwc2FfFkkb0ltl-tw3cxOw4-gA","y":"4cQ7HDVN7ukSWcAeQcg2QrIMLwluObrU5Dfsem7ZIOY","ext":true,"key_ops":["verify"]};

  var core = window.DNLicenseCore;

  function fmtDate(ymd) {
    var p = String(ymd).split('-');
    return p.length === 3 ? (p[0] + '年' + parseInt(p[1], 10) + '月' + parseInt(p[2], 10) + '日') : ymd;
  }

  function getTermsStore() {
    try { return JSON.parse(localStorage.getItem(TERMS_KEY) || '{}'); } catch (e) { return {}; }
  }

  function isTermsAccepted() {
    var rec = getTermsStore()[APP];
    return !!(rec && rec.version === TERMS_VERSION && rec.acceptedAt);
  }

  function saveTermsAcceptance() {
    var all = getTermsStore();
    all[APP] = {
      version: TERMS_VERSION,
      acceptedAt: new Date().toISOString(),
      app: APP
    };
    try { localStorage.setItem(TERMS_KEY, JSON.stringify(all)); } catch (e) {}
  }

  window.DNTerms = {
    version: TERMS_VERSION,
    isAccepted: isTermsAccepted,
    getRecord: function () { return getTermsStore()[APP] || null; },
    getAllRecords: getTermsStore
  };

  function addWatermark(exp) {
    if (document.getElementById('dn-license-watermark')) return;
    var el = document.createElement('div');
    el.id = 'dn-license-watermark';
    el.setAttribute('aria-hidden', 'true');
    el.style.cssText = 'position:fixed;bottom:8px;right:12px;z-index:9998;font-size:11px;color:rgba(80,80,80,0.30);pointer-events:none;user-select:none;white-space:nowrap;';
    el.textContent = CONTACT_LABEL + '　有効期限:～' + fmtDate(exp);
    document.body.appendChild(el);
  }

  function overlayBase(maxWidth) {
    var o = document.createElement('div');
    o.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;padding:1.5rem;';
    var card = document.createElement('div');
    card.style.cssText = 'background:#fff;border-radius:12px;padding:2rem 2.5rem;max-width:' + (maxWidth || 440) + 'px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.2);font-family:-apple-system,"Segoe UI","Yu Gothic",sans-serif;';
    o.appendChild(card);
    return { overlay: o, card: card };
  }

  function showTerms(onAccept) {
    document.documentElement.style.overflow = 'hidden';
    var b = overlayBase(520);
    b.card.innerHTML =
      '<h2 style="margin:0 0 1rem;font-size:1.2rem;color:#1a2433;text-align:center;">利用前の確認</h2>' +
      '<div style="text-align:left;color:#333;font-size:0.92rem;line-height:1.75;">' +
        '<p style="margin:0 0 0.75rem;"><strong>データの取り扱い</strong><br>入力データは端末内にのみ保存され、外部サーバーへ送信されません。</p>' +
        '<p style="margin:0;"><strong>免責事項</strong><br>本アプリの操作・利用により生じた損害について、開発者は責任を負いません。</p>' +
      '</div>' +
      '<label style="display:flex;align-items:flex-start;gap:8px;margin:1.1rem 0 0.5rem;font-size:0.9rem;color:#333;cursor:pointer;text-align:left;">' +
        '<input type="checkbox" id="dn-terms-check" style="margin-top:3px;width:16px;height:16px;flex-shrink:0;">' +
        '<span>上記の内容を理解し、同意します。</span>' +
      '</label>' +
      '<div style="text-align:center;margin-top:1rem;">' +
        '<button id="dn-terms-submit" disabled style="background:#154C87;color:#fff;border:0;border-radius:8px;padding:0.65rem 1.6rem;font-size:0.95rem;cursor:pointer;opacity:0.45;">同意して使う</button>' +
      '</div>';
    document.documentElement.appendChild(b.overlay);

    var chk = b.card.querySelector('#dn-terms-check');
    var btn = b.card.querySelector('#dn-terms-submit');
    chk.addEventListener('change', function () {
      btn.disabled = !chk.checked;
      btn.style.opacity = chk.checked ? '1' : '0.45';
      btn.style.cursor = chk.checked ? 'pointer' : 'not-allowed';
    });
    btn.addEventListener('click', function () {
      if (!chk.checked) return;
      saveTermsAcceptance();
      document.documentElement.style.overflow = '';
      b.overlay.remove();
      if (typeof onAccept === 'function') onAccept();
    });
  }

  function showExpired(exp) {
    document.documentElement.style.overflow = 'hidden';
    var b = overlayBase();
    b.card.style.textAlign = 'center';
    b.card.innerHTML =
      '<div style="font-size:2.5rem;margin-bottom:0.5rem;">🔒</div>' +
      '<h2 style="margin:0 0 0.75rem;font-size:1.25rem;color:#1a2433;">使用期限が終了しました</h2>' +
      '<p style="margin:0 0 0.5rem;color:#444;line-height:1.6;">有効期限（～' + fmtDate(exp) + '）が過ぎています。</p>' +
      '<p style="margin:0 0 1rem;color:#666;font-size:0.9rem;line-height:1.5;">継続利用は配布元までお問い合わせください。</p>' +
      '<p style="margin:0;font-size:0.85rem;color:#888;">' + CONTACT_LABEL + '</p>';
    document.documentElement.appendChild(b.overlay);
  }

  function reasonMessage(r) {
    return {
      format: 'コードが正しくありません。',
      signature: 'コードが正しくありません。',
      app: 'このコードは別のアプリ用です。',
      expired: '有効期限が切れています。',
      key: '検証に失敗しました（鍵エラー）。'
    }[r.reason] || 'コードが正しくありません。';
  }

  function showEntry() {
    document.documentElement.style.overflow = 'hidden';
    var b = overlayBase(480);
    b.card.style.textAlign = 'center';
    b.card.innerHTML =
      '<div style="font-size:2.2rem;margin-bottom:0.5rem;">🔑</div>' +
      '<h2 style="margin:0 0 0.5rem;font-size:1.2rem;color:#1a2433;">利用コードを入力してください</h2>' +
      '<p style="margin:0 0 1rem;color:#555;font-size:0.9rem;line-height:1.6;text-align:left;">無料で利用できます。ホームページからメールを登録すると利用コードが届きます。</p>' +
      '<input type="text" id="dn-code-input" autocomplete="off" spellcheck="false" style="width:100%;box-sizing:border-box;padding:0.6rem;border:1px solid #ccc;border-radius:8px;font-size:0.75rem;font-family:Consolas,monospace;white-space:nowrap;overflow-x:auto;" placeholder="ここにコードを貼り付け（1行）">' +
      '<div id="dn-code-error" style="min-height:1.2em;margin:0.5rem 0;color:#b23a2e;font-size:0.85rem;"></div>' +
      '<button id="dn-code-submit" style="background:#154C87;color:#fff;border:0;border-radius:8px;padding:0.6rem 1.4rem;font-size:0.95rem;cursor:pointer;">認証</button>';
    document.documentElement.appendChild(b.overlay);

    var input = b.card.querySelector('#dn-code-input');
    var err = b.card.querySelector('#dn-code-error');
    var btn = b.card.querySelector('#dn-code-submit');

    btn.addEventListener('click', async function () {
      err.textContent = '';
      btn.disabled = true;
      btn.textContent = '認証中…';
      var code = core.normalizeCode(input.value || '');
      var r = await core.verifyLicense(code, APP, PUBLIC_JWK, Date.now());
      btn.disabled = false;
      btn.textContent = '認証';
      if (r.valid) {
        try { localStorage.setItem(STORAGE_KEY, code); } catch (e) {}
        document.documentElement.style.overflow = '';
        b.overlay.remove();
        addWatermark(r.exp);
        return;
      }
      if (r.reason === 'expired') {
        err.textContent = '';
        b.overlay.remove();
        showExpired(r.exp);
        return;
      }
      err.textContent = reasonMessage(r);
    });
  }

  async function startLicenseFlow() {
    if (!core || !APP) { showEntry(); return; }
    var saved = null;
    try { saved = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    if (saved) {
      var r = await core.verifyLicense(saved, APP, PUBLIC_JWK, Date.now());
      if (r.valid) { addWatermark(r.exp); return; }
      if (r.reason === 'expired') { showExpired(r.exp); return; }
    }
    showEntry();
  }

  function init() {
    if (!isTermsAccepted()) {
      showTerms(startLicenseFlow);
      return;
    }
    startLicenseFlow();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
